using System;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.UI;
public static class NWPerformance {
 public static IEnumerator Run(NWProbe p){yield return p.Wait(()=>CP05Training.Instance?.Hero!=null,15);for(int type=11;type<11+NewWeaponRegistry.EnabledCount;type++)for(int slot=-1;slot<2;slot++){var old=CP05Training.Instance.Hero;CP05Training.Instance.RequestRestart();yield return p.Wait(()=>CP05Training.Instance.Hero!=old&&!CP05Training.Instance.Restarting,6);yield return p.Wait(()=>UnityEngine.Object.FindObjectsByType<Button>().Any(b=>b.name=="训练装备架"),5);var h=CP05Training.Instance.Hero;UnityEngine.Object.FindObjectsByType<Button>().Single(b=>b.name=="训练装备架").onClick.Invoke();yield return null;yield return null;var drop=UnityEngine.Object.FindObjectsByType<LootPickup>().Single(l=>l.Gear!=null&&(int)l.Gear.type==type);p.Check("perf-pickup-"+type+"-"+slot,drop.PickUp(h.Inventory));var c=h.GetComponent<AdventureCombat>();p.Check("perf-equip-"+type+"-"+slot,c.Gear.SelectMain(drop.Gear));yield return new WaitForSeconds(.3f);h.transform.rotation=Quaternion.identity;for(int k=0;k<CP05Training.Instance.Enemies.Length;k++){var e=CP05Training.Instance.Enemies[k];e.enabled=false;var cc=e.GetComponent<CharacterController>();cc.enabled=false;e.transform.position=h.transform.position+new Vector3(k==0?-.45f:.45f,0,1.5f);cc.enabled=true;}PlayerInput.Focus(true);if(slot>=0)c.NewWeapons.Select(slot);yield return null;yield return null;p.Check("perf-real-request-"+type+"-"+slot,slot<0?c.Strike():c.UseSkill());yield return new WaitForSeconds(1.8f);p.Check("perf-action-completes-"+type+"-"+slot,!c.NewWeapons.Busy);}
 yield return new WaitForSeconds(.7f);p.Check("perf-bounded-effects",UnityEngine.Object.FindObjectsByType<NewWeaponArc>().Length==0&&UnityEngine.Object.FindObjectsByType<NewWeaponTrace>().Length==0&&UnityEngine.Object.FindObjectsByType<NewGroundShock>().Length==0,"actual effects finished, per-scene resources cleaned on restart; not a long-duration benchmark");
 }
}
